import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String w = st.nextToken();
            // On a clash, replace the current character; it can always differ from both sides.
            int changes = 0;
            char last = 0;
            for (int k = 0; k < w.length(); k++) {
                char c = w.charAt(k);
                if (c == last) {
                    changes++;
                    last = 0;
                } else last = c;
            }
            if (i > 0) sb.append(' ');
            sb.append(changes);
        }
        System.out.print(sb.append('\n'));
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		sc.Scan()
		// On a clash, replace the current character; it can always differ from both sides.
		changes := 0
		var last byte
		for _, c := range sc.Bytes() {
			if c == last {
				changes++
				last = 0
			} else {
				last = c
			}
		}
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(changes))
	}
	w.WriteByte('\n')
}
